import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = [int(x) for x in input_data[1:n+1]]

    # dp[i][0] = min rest days up to day i, where day i is rest
    # dp[i][1] = min rest days up to day i, where day i is contest
    # dp[i][2] = min rest days up to day i, where day i is sport

    INF = float('inf')

    # Initialize for day 1 (index 0)
    day_type = a[0]

    # Option 0: Rest
    dp0 = 1
    # Option 1: Contest
    if day_type == 1 or day_type == 3:
        dp1 = 1
    else:
        dp1 = INF
    # Option 2: Sport
    if day_type == 2 or day_type == 3:
        dp2 = 1
    else:
        dp2 = INF

    for i in range(1, n):
        day_type = a[i]

        new_dp0 = 1 + min(dp0, dp1, dp2)

        new_dp1 = INF
        if day_type == 1 or day_type == 3:
            # Can do contest if previous was rest or sport (not contest)
            if dp0 != INF:
                new_dp1 = min(new_dp1, dp0 + 1)
            if dp2 != INF:
                new_dp1 = min(new_dp1, dp2)

        new_dp2 = INF
        if day_type == 2 or day_type == 3:
            # Can do sport if previous was rest or contest (not sport)
            if dp0 != INF:
                new_dp2 = min(new_dp2, dp0 + 1)
            if dp1 != INF:
                new_dp2 = min(new_dp2, dp1)

        dp0, dp1, dp2 = new_dp0, new_dp1, new_dp2

    print(min(dp0, dp1, dp2))

if __name__ == '__main__':
    solve()
